challenge.solution:
가장수 = 1
가장걸음 = 0
for 시작 in range(1, 101):
    수 = 시작
    걸음 = 0
    while 수 != 1:
        if 수 % 2 == 0:
            수 = 수 // 2
        else:
            수 = 수 * 3 + 1
        걸음 += 1
    if 걸음 > 가장걸음:
        가장수 = 시작
        가장걸음 = 걸음
print(가장수, 가장걸음)
